MOD = 998244353

def count_good_permutations(n, s):
    def inversions(arr):
        return sum(arr[i] > arr[j] for i in range(len(arr)) for j in range(i + 1, len(arr)))

    def mod_inv(x):
        return pow(x, MOD - 2, MOD)

    def nCr(n, r):
        return factorial(n) * mod_inv(factorial(r)) % MOD * mod_inv(factorial(n - r)) % MOD

    def count_sorted_by_first():
        freq = [0] * (n + 1)
        for _, b in s:
            freq[b] += 1
        return sum(inversions(freq))

    def count_sorted_by_second():
        freq = [0] * (n + 1)
        for a, _ in s:
            freq[a] += 1
        return sum(inversions(freq))

    def count_both_sorted():
        freq = [0] * (n + 1)
        for a, b in s:
            freq[min(a, b)] += 1
        return sum(inversions(freq))

