        return arr == sorted(arr)

    def count_valid_sequences(n, s):
        dp = [[0] * (n + 1) for _ in range(2)]
        dp[0][0] = 1
        for i in range(n):
            new_dp = [[0] * (n + 1) for _ in range(2)]
            for j in range(n + 1):
                if j > 0:
                    new_dp[0][j] += dp[0][j - 1]
                    new_dp[0][j] %= MOD
                if j < n:
                    new_dp[1][j] += dp[1][j + 1]
                    new_dp[1][j] %= MOD
                if j > 0 and j < n:
                    if s[i][0] >= s[i - 1][0]:
                        new_dp[0][j] += dp[0][j - 1]
                        new_dp[0][j] %= MOD
                    if s[i][1] >= s[i - 1][1]:
                        new_dp[1][j] += dp[1][j + 1]
                        new_dp[1][j] %= MOD
            dp = new_dp
        return sum(dp[0]) % MOD + sum(dp[1]) % MOD - 1

    def count_invalid_sequences(n, s):
        return count_valid_sequences(n, s) - count_sorted([x[0] for x in s]) - count_sorted([x[1] for x in s])

    return pow(factorial(n), MOD - 2, MOD) * (count_valid_sequences(n, s) - count_invalid_sequences(n, s)) % MOD

